<script setup lang="ts">
import { ref } from 'vue'
import { post,get } from '../api/client'
import type { Preparation,Model,Page } from '../api/types'
import { session } from '../composables/session'
import { useQuery } from '../composables/useQuery'
import { useMutation } from '../composables/useMutation'
import { integerText,ratioText } from '../api/format'
import Feedback from './Feedback.vue'
const props=defineProps<{versionId:string;budget?:Model<'RuntimeSupervisionContract'>|null;purpose?:string;runId?:string}>(),emit=defineEmits<{created:[id:string]}>(),op=useMutation()
const purpose=ref(props.purpose||'execute_etl'),environment=ref('test'),runId=ref(props.runId||''),confirmed=ref(false),dataset=ref('')
const maxInput=ref(props.budget?.max_input_records||'1000000'),maxBytes=ref(props.budget?.max_output_bytes||'1073741824'),duration=ref(props.budget?.max_duration_ms||'3600000'),amplification=ref(props.budget?.max_amplification_ratio||'10'),rejection=ref(props.budget?.max_rejection_ratio||'0.05'),exceed=ref(props.budget?.on_exceed||'kill')
const datasets=useQuery(s=>purpose.value==='run_l2_benchmark'?get<Page<Model<'BenchmarkDatasetResponse'>>>(`/api/v1/projects/${session.project!.id}/benchmark-datasets?limit=100`,s):Promise.resolve({data:{items:[],has_more:false,next_cursor:null,request_id:''},etag:null,requestId:''}),[purpose])
async function submit(){await op.run(async()=>{const set=datasets.data.value?.items.find(d=>d.id===dataset.value);if(purpose.value==='run_l2_benchmark'&&!set)throw new Error('请先选择已有的版本化用例集');if(!/^\d+(\.\d+)?$/.test(amplification.value))throw new Error('放大比必须是精确十进制文本');const r=await post<Preparation>(`/api/v1/versions/${props.versionId}/prepare`,{purpose:purpose.value,environment:environment.value,execution_run_id:purpose.value==='rollback'?runId.value:null,evaluation_binding:purpose.value==='run_l2_benchmark'?{dataset_id:set!.id,dataset_digest:set!.content_digest,provider_binding:{provider:'deepseek',model:import.meta.env.VITE_MODEL_NAME||'deepseek-v4.1-flash',prompt_version:'v1',policy_version:'1'}}:null,supervision_contract:{schema_version:1,max_input_records:integerText(maxInput.value),max_output_bytes:integerText(maxBytes.value),max_duration_ms:integerText(duration.value),max_amplification_ratio:amplification.value,max_rejection_ratio:ratioText(rejection.value),on_exceed:exceed.value}});emit('created',r.data.preparation.id);return r})}
</script>
<template><form @submit.prevent="submit"><div class="form-grid"><label class="field">准备用途<select v-model="purpose" name="purpose" :disabled="!!props.purpose"><option value="execute_etl">正式执行</option><option value="isolated_trial">隔离真实试运行</option><option value="run_l2_benchmark">L2 真实评测</option><option v-if="props.runId" value="rollback">回滚</option></select></label><label class="field">申请环境<input v-model="environment" name="environment" required/><small>实际环境范围由服务端校验</small></label><label v-if="purpose==='rollback'" class="field full">原运行 UUID<input v-model="runId" name="runId" required :readonly="!!props.runId"/></label><label v-if="purpose==='run_l2_benchmark'" class="field full">版本化用例集<select v-model="dataset" name="dataset" required><option value="">选择已有用例集</option><option v-for="d in datasets.data.value?.items||[]" :key="d.id" :value="d.id">{{d.name}} · {{d.version}}</option></select></label><label class="field">最大读取行数<input v-model="maxInput" name="maxInput" required inputmode="numeric" pattern="[0-9]+"/></label><label class="field">最大输出字节数<input v-model="maxBytes" name="maxBytes" required inputmode="numeric" pattern="[0-9]+"/></label><label class="field">最长运行时长（毫秒）<input v-model="duration" name="duration" required inputmode="numeric" pattern="[0-9]+"/></label><label class="field">最大输出放大比<input v-model="amplification" name="amplification" required inputmode="decimal"/></label><label class="field">最大拒绝率（0—1）<input v-model="rejection" name="rejection" required inputmode="decimal"/></label><label class="field">越限动作<select v-model="exceed" name="exceed"><option value="kill">请求受管停止</option><option value="warn">预警</option><option value="isolate_alert">隔离告警</option></select></label></div><div class="block-note">准备不会启动实际作业。服务端将冻结资源、分级、预算、回滚范围和输入指纹，并建立独立审批。</div><label class="profile-check"><input v-model="confirmed" name="confirmed" type="checkbox" required/>我已核对用途、环境和上述预算，申请冻结这些事实。</label><Feedback :error="op.error.value||datasets.error.value" :unknown="op.unknown.value"/><div class="form-actions"><button class="button primary" :disabled="!confirmed||op.busy.value||op.unknown.value">{{op.busy.value?'正在创建准备单…':'创建准备单并进入审查'}}</button></div></form></template>
